-- select passengers.name, ports.city from passengers join ports on ports.id = passengers.portId ;
-- \i titanic.sql



CREATE TABLE IF NOT EXISTS ports(
  id INT, 
  embarked VARCHAR(1), 
  city VARCHAR(100)
);

CREATE TABLE IF NOT EXISTS passengers(
  id INT, 
  survived DECIMAL(10, 2), 
  pclass DECIMAL(10, 2), 
  name VARCHAR(100), 
  sex VARCHAR(6), 
  age DECIMAL(10, 2), 
  sibsp INT, 
  parch INT, 
  cabin VARCHAR(100), 
  ticketId INT, 
  portId INT
);


